mapper.update:
update bbs_idea_proposal
title = #{title}, category = #{category}, content = #{content}, background_text = #{backgroundText}, plan_text = #{planText}, expected_value = #{expectedValue}, visibility_scope = #{visibilityScope}, attachment_urls = #{attachmentUrls}, related_case = #{relatedCase}, team_name = #{teamName}, is_draft = #{isDraft}, review_stage = #{reviewStage}, review_deadline = #{reviewDeadline}, biz_value = #{bizValue}, status = #{status}, update_time = now()
where idea_id = #{ideaId}

mapper.select:
select i.idea_id, i.title, i.category, i.content, i.background_text, i.plan_text, i.expected_value, i.visibility_scope, i.attachment_urls, i.related_case, i.team_name, i.is_draft, i.review_stage, i.reject_reason, i.project_time, i.landing_time, i.is_publicized, i.incentive_points, i.honor_badge, i.like_count, i.share_count, i.review_deadline, i.biz_value, i.status, i.avg_score, i.result_summary, i.submit_user_id, i.submit_nick_name, i.create_time, i.update_time from bbs_idea_proposal i
i.del_flag = '0' and i.status = #{status} and i.category = #{category} and i.is_publicized = #{isPublicized}
and (i.title like concat('%', #{keyword}, '%') or i.content like concat('%', #{keyword}, '%'))
and ( #{mineOnly} = 1 or i.is_publicized = '1' or i.submit_user_id = #{currentUserId} or #{canReviewAll} = 1 or exists (select 1 from bbs_idea_review r where r.idea_id = i.idea_id and r.reviewer_user_id = #{currentUserId}) ) and i.submit_user_id = #{currentUserId}
order by i.create_time desc

select count(1)
from bbs_idea_proposal
where submit_user_id = #{submitUserId}
  and title = #{title}
  and del_flag = '0'
  and date(create_time) = curdate()

mapper.update:
update bbs_idea_proposal
set avg_score = #{avgScore}, update_time = now()
where idea_id = #{ideaId}

mapper.select:
select ifnull(avg(score), 0)
from bbs_idea_review
where idea_id = #{ideaId}

mapper.update:
update bbs_idea_proposal
set status = #{status}, update_time = now()
where idea_id = #{ideaId}

update bbs_idea_proposal
set status = 'LANDED', landing_time = #{landingTime}, update_time = now()
where idea_id = #{ideaId}

update bbs_idea_proposal
set like_count = like_count + 1, update_time = now()
where idea_id = #{ideaId}

update bbs_idea_proposal
set share_count = share_count + 1, update_time = now()
where idea_id = #{ideaId}

mapper.select:
select review_id, idea_id, stage, action,
       reviewer_user_id, reviewer_nick_name,
       score, comment, reject_reason,
       is_visible_to_all, review_time, create_time
from bbs_idea_review
where idea_id = #{ideaId}
  and stage = #{stage}
  and reviewer_user_id = #{reviewerUserId}
order by create_time desc
limit 1
